when.condition:
@{
        if (context.Response.StatusCode != 403) { return false; }
        var body = context.Response.Body?.As<JObject>(preserveContent: true);
        if (body == null || body["error"] != null || body["statusCode"] == null) { return false; }
        var msg = (string)body["message"] ?? "";
        return msg.ToLowerInvariant().Contains("content safety");
    }
